const parseHex = (hex) => {
  const m = /^#?([0-9a-f]{2})([0-9a-f]{2})([0-9a-f]{2})$/i.exec(hex);
  if (!m) return null;
  return m.slice(1).map((h) => parseInt(h, 16));
};

