export class Ring<T> {
  private items: (T | undefined)[];
  private head = 0;
  constructor(private size: number) {
    this.items = new Array(size);
  }
  push(value: T): void {
    this.items[this.head] = value;
    this.head = (this.head + 1) % this.size;
  }
  toArray(): T[] {
    return this.items.filter((x): x is T => x !== undefined);
  }
}

