type RGB = [number, number, number];

const lerp = (a: number, b: number, t: number) => a + (b - a) * t;

export function mix(from: RGB, to: RGB, t: number): RGB {
  const k = Math.min(1, Math.max(0, t));
  return from.map((c, i) => Math.round(lerp(c, to[i], k))) as RGB;
}

type Events = { press: string; release: string; idle: number };

class Emitter<E extends Record<string, unknown>> {
  private map = new Map<keyof E, Set<(p: never) => void>>();
  on<K extends keyof E>(event: K, fn: (payload: E[K]) => void) {
    if (!this.map.has(event)) this.map.set(event, new Set());
    this.map.get(event)!.add(fn as (p: never) => void);
    return () => this.map.get(event)!.delete(fn as (p: never) => void);
  }
}

