def slowest_keys(times: dict[str, list[float]], top: int = 3):
    averages = {
        key: sum(ms) / len(ms)
        for key, ms in times.items()
        if ms
    }
    return sorted(averages.items(), key=lambda kv: kv[1], reverse=True)[:top]

