import time
from functools import wraps

def retry(times=3, delay=0.5):
    def wrap(fn):
        @wraps(fn)
        def inner(*args, **kwargs):
            for attempt in range(times):
                try:
                    return fn(*args, **kwargs)
                except OSError:
                    time.sleep(delay * (attempt + 1))
            return fn(*args, **kwargs)
        return inner
    return wrap

