fn fade(from: [u8; 3], to: [u8; 3], t: f32) -> [u8; 3] {
    let t = t.clamp(0.0, 1.0);
    let mut out = [0u8; 3];
    for i in 0..3 {
        let a = from[i] as f32;
        let b = to[i] as f32;
        out[i] = (a + (b - a) * t).round() as u8;
    }
    out
}

