pub struct Ring<T, const N: usize> {
    items: [Option<T>; N],
    head: usize,
}

impl<T: Copy, const N: usize> Ring<T, N> {
    pub fn push(&mut self, value: T) {
        self.items[self.head] = Some(value);
        self.head = (self.head + 1) % N;
    }
    pub fn len(&self) -> usize {
        self.items.iter().filter(|x| x.is_some()).count()
    }
}

fn average_wpm(results: &[(String, f32)]) -> Option<f32> {
    if results.is_empty() {
        return None;
    }
    let total: f32 = results.iter().map(|(_, wpm)| wpm).sum();
    Some(total / results.len() as f32)
}

package stats

type KeyStat struct {
  Hits, Misses int
}

func Accuracy(stats map[string]KeyStat) float64 {
  hits, total := 0, 0
  for _, s := range stats {
    hits += s.Hits
    total += s.Hits + s.Misses
  }
  if total == 0 {
    return 1
  }
  return float64(hits) / float64(total)
}

func pressAll(codes []string) <-chan string {
  out := make(chan string, len(codes))
  go func() {
    defer close(out)
    for _, c := range codes {
      out <- strings.ToUpper(c)
    }
  }()
  return out
}

func loadProfile(path string) (*Profile, error) {
  data, err := os.ReadFile(path)
  if err != nil {
    return nil, fmt.Errorf("read %s: %w", path, err)
  }
  var p Profile
  if err := json.Unmarshal(data, &p); err != nil {
    return nil, fmt.Errorf("parse %s: %w", path, err)
  }
  return &p, nil
}

func handleColor(w http.ResponseWriter, r *http.Request) {
  hex := r.URL.Query().Get("hex")
  if len(hex) != 6 {
    http.Error(w, "expected 6 hex digits", http.StatusBadRequest)
    return
  }
  w.Header().Set("Content-Type", "application/json")
  fmt.Fprintf(w, `{"color":"#%s"}`, hex)
}

